from pathlib import Path
import json,html,re,hashlib
out=Path('output/source-page-append-verification')
def load(file):return json.loads((out/file).read_text(encoding='utf8'))
rows=[]
for label,file in [('รับข้อมูล/บันทึก/Frozen','setup-results.json'),('ส่งออกจริง','exports-results.json'),('สำรอง/คืนข้อมูล','restore-results.json'),('แอปที่ build แล้ว','compiled-results.json')]:
    d=load(file);assert not d['cloud'] and not d['errors'] and not d['productionRequests']
    for r in d['results']:
        assert r['status']=='PASS';rows.append(f'<tr><td>{label}</td><td>{html.escape(r["name"])}</td><td class="pass">ผ่าน</td></tr>')
pdfs=load('pdf-audit.json');assert sum(r['pages'] for r in pdfs)==182 and all(len(r['all55SourceShapes'])==55 for r in pdfs);assert load('excel-view-results.json')['unmappedBBSCellsRemainBlank']
for file in ['protected-config.json','reference-checksums.json']:assert all(r['unchanged'] for r in load(file))
for r in load('artifact-hashes.json'):assert hashlib.sha256((out/r['name']).read_bytes()).hexdigest()==r['sha256']
assert '1544 passed (1544)' in (out/'unit-tests.log').read_text(encoding='utf8');assert 'built in' in (out/'build.log').read_text(encoding='utf8')
