fileLinks='<a href="B104-Source-Pages.xlsx">Excelตารางอ้างอิง</a> · '+ ' · '.join(f'<a href="{p["file"]}">PDF{p["size"]} / {p["pages"]}หน้า / {p["bytes"]/1024/1024:.3f}MiB</a>' for p in pdfs)
